    static JSONObject object(Object o)throws IOException{if(!(o instanceof JSONObject))throw new IOException("来源数据结构已改变");return (JSONObject)o;}
    static JSONObject data(String source,String path,boolean cache)throws Exception{JSONObject o=object(HttpData.json(HttpData.get(Feeds.absolute(base(source),path),base(source)+"/",cache).body));if(o.has("code")&&o.optInt("code")!=200&&o.optInt("code")!=0)throw new IOException("来源暂不可用："+Feeds.str(o,"message","msg"));return o;}
    static String text(Element root,String selector){for(Element e:root.select(selector))if(!e.text().trim().isEmpty())return e.text().trim();return "";}
