        if(source.equals(JR)){String html="";try{html=HttpData.get(base(source)+"/",base(source)+"/",true).body;}catch(IOException ignored){}Document doc=Jsoup.parse(html,base(source));String index="https://im-imgs-bucket.oss-accelerate.aliyuncs.com/index.js?t_5";for(Element script:doc.select("script[src]"))if(script.attr("src").contains("/index.js"))index=Feeds.absolute(base(source),script.attr("src"));return page(parseJrkan(html,HttpData.get(index,base(source)+"/",true).body,view),number);}
