    public static List<Feeds.Match> parseRain(JSONObject response,String view)throws Exception{JSONArray a=response.getJSONObject("data").getJSONArray("matches");ArrayList<Feeds.Match> result=new ArrayList<Feeds.Match>();for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);TeamNames.learn(o);JSONArray anchors=o.optJSONArray("anchors");if(view.equals("live")&&(anchors==null||anchors.length()==0))continue;Feeds.Match m=match(RAIN,Feeds.str(o,"scheduleId"));m.home=Feeds.str(o,"hostName");m.away=Feeds.str(o,"guestName");m.title=m.home+" vs "+m.away;m.sport=Feeds.str(o,"categoryId");m.league=Feeds.str(o,"subCateName");m.time=time(o.optLong("matchTime"));m.status=o.optInt("status")==1?"live":"upcoming";m.eventState=o.optInt("status")==1?"live":"";m.score=Feeds.str(o,"hostScore")+" : "+Feeds.str(o,"guestScore");m.room=m.id;m.raw.put("anchors",anchors==null?new JSONArray():anchors);pack(m);result.add(m);}return result;}
